INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_001', 'math', 'คณิตศาสตร์', 'Regular', 1, 'ค่าประจำหลักและจำนวนนับ', 'เลข 5 ในจำนวน 351000 กับเลข 5 ในจำนวน 70510 มีค่าต่างกันเท่าใด', '["45,000","49,500","50,000","50,500"]', 1, 'นำค่าประจำหลักในหลักหมื่น (50,000) ลบค่าประจำหลักในหลักร้อย (500) ได้ 49,500', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ค่าประจำหลักและจำนวนนับ","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_002', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การประมาณค่าใกล้เคียง', 'ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84672 คือข้อใด', '["84,000","84,700","85,000","85,600"]', 2, 'ดูหลักร้อยเป็นเลข 6 (มากกว่าหรือเท่ากับ 5) ให้ปัดขึ้นเป็น 85,000', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["การประมาณค่าใกล้เคียง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_003', 'math', 'คณิตศาสตร์', 'Regular', 1, 'สมบัติการแจกแจง', '\( (33 \times 65) + (33 \times 35) \) มีค่าเท่ากับข้อใด', '["3300","2970","2640","3630"]', 0, 'ดึงตัวร่วม: 33 x (65 + 35) = 33 x 100 = 3300', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["สมบัติการแจกแจง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_004', 'math', 'คณิตศาสตร์', 'Regular', 1, 'ห.ร.ม. และ ค.ร.น.', 'สองจำนวนมี ห.ร.ม. = 6 และ ค.ร.น. = 168 ถ้าจำนวนแรกคือ 24 อีกจำนวนคือข้อใด', '["42","52","37","57"]', 0, 'ใช้สูตร: จำนวนที่สอง = (ห.ร.ม. x ค.ร.น.) / จำนวนแรก', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ห.ร.ม. และ ค.ร.น.","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_005', 'math', 'คณิตศาสตร์', 'Regular', 1, 'เศษส่วนต่อเนื่องและเศษส่วนซ้อน', 'ถ้า \( \displaystyle x = 1 + \cfrac{1}{2 + \cfrac{1}{8}} \) จงหาค่าของ x ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{25}{17} \\)","\\( \\displaystyle \\frac{24}{17} \\)","\\( \\displaystyle \\frac{27}{17} \\)","\\( \\displaystyle \\frac{8}{17} \\)"]', 0, 'คำนวณจากชั้นล่างสุดขึ้นมาด้านบน: ตีลังกากลับเศษส่วนแล้วบวกตัวหน้า', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["เศษส่วนต่อเนื่องและเศษส่วนซ้อน","Regular","L1"]');
