INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_023', 'math', 'คณิตศาสตร์', 'Regular', 1, 'การประมาณค่าใกล้เคียง', 'ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84693 คือข้อใด', '["84,000","84,700","85,000","85,600"]', 2, 'ดูหลักร้อยเป็นเลข 6 (มากกว่าหรือเท่ากับ 5) ให้ปัดขึ้นเป็น 85,000', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["การประมาณค่าใกล้เคียง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L1_024', 'math', 'คณิตศาสตร์', 'Regular', 1, 'สมบัติการแจกแจง', '\( (54 \times 65) + (54 \times 35) \) มีค่าเท่ากับข้อใด', '["5400","4860","4320","5940"]', 0, 'ดึงตัวร่วม: 54 x (65 + 35) = 54 x 100 = 5400', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["สมบัติการแจกแจง","Regular","L1"]');
