INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_L2_019', 'math', 'คณิตศาสตร์', 'Regular', 2, 'การประมาณค่าใกล้เคียง', 'ค่าประมาณใกล้เคียงจำนวนเต็มพันของ 84689 คือข้อใด', '["84,000","84,700","85,000","85,600"]', 2, 'ดูหลักร้อยเป็นเลข 6 (มากกว่าหรือเท่ากับ 5) ให้ปัดขึ้นเป็น 85,000', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["การประมาณค่าใกล้เคียง","Regular","L2"]');
