INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_M_018', 'math', 'คณิตศาสตร์', 'Regular', 2, 'สมบัติการแจกแจง', '\( (48 \times 65) + (48 \times 35) \) มีค่าเท่ากับข้อใด', '["4800","4320","3840","5280"]', 0, 'ดึงตัวร่วม: 48 x (65 + 35) = 48 x 100 = 4800', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["สมบัติการแจกแจง","Regular","M"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_M_019', 'math', 'คณิตศาสตร์', 'Regular', 2, 'ห.ร.ม. และ ค.ร.น.', 'สองจำนวนมี ห.ร.ม. = 6 และ ค.ร.น. = 348 ถ้าจำนวนแรกคือ 24 อีกจำนวนคือข้อใด', '["87","97","82","102"]', 0, 'ใช้สูตร: จำนวนที่สอง = (ห.ร.ม. x ค.ร.น.) / จำนวนแรก', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ห.ร.ม. และ ค.ร.น.","Regular","M"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('MATH_M_020', 'math', 'คณิตศาสตร์', 'Regular', 2, 'เศษส่วนต่อเนื่องและเศษส่วนซ้อน', 'ถ้า \( \displaystyle x = 1 + \cfrac{1}{2 + \cfrac{1}{23}} \) จงหาค่าของ x ในรูปเศษส่วนอย่างต่ำ', '["\\( \\displaystyle \\frac{70}{47} \\)","\\( \\displaystyle \\frac{69}{47} \\)","\\( \\displaystyle \\frac{72}{47} \\)","\\( \\displaystyle \\frac{23}{47} \\)"]', 0, 'คำนวณจากชั้นล่างสุดขึ้นมาด้านบน: ตีลังกากลับเศษส่วนแล้วบวกตัวหน้า', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["เศษส่วนต่อเนื่องและเศษส่วนซ้อน","Regular","M"]');
