INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_L1_001', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ชีววิทยา: ท่อลำเลียงพืช', 'เนื้อเยื่อ โฟลเอ็ม (Phloem) ในพืชทำหน้าที่และมีทิศทางอย่างไร (ข้อที่ 1)', '["ลำเลียงอาหารจากใบไปทั่วทุกส่วนได้ทุกทิศทาง","ลำเลียงน้ำจากรากขึ้นบนเท่านั้น","ลำเลียงแก๊สออกซิเจน","ลำเลียงฮอร์โมนลงล่างอย่างเดียว"]', 0, 'ไซเล็มลำเลียงน้ำและแร่ธาตุขึ้นบน ส่วนโฟลเอ็มลำเลียงอาหารได้ทุกทิศทาง', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ชีววิทยา: ท่อลำเลียงพืช","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_L1_002', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'ชีววิทยา: การสังเคราะห์ด้วยแสง', 'สารใดเป็นผลผลิตหลักจากการสังเคราะห์ด้วยแสงของพืชควบคู่กับแก๊สออกซิเจน (ข้อที่ 2)', '["น้ำตาลกลูโคส","แก๊สคาร์บอนไดออกไซด์","กรดอะมิโน","ไขมัน"]', 0, 'ปฏิกิริยาสังเคราะห์ด้วยแสงเปลี่ยน CO2 + H2O ได้น้ำตาลกลูโคสและออกซิเจน', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ชีววิทยา: การสังเคราะห์ด้วยแสง","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_L1_003', 'science', 'วิทยาศาสตร์', 'Regular', 1, 'พันธุศาสตร์: หมู่เลือด ABO', 'พ่อเลือดหมู่ A (IA i) แม่เลือดหมู่ B (IB i) ลูกมีโอกาสมีเลือดหมู่ใดได้บ้าง (ข้อที่ 3)', '["มีโอกาสเป็นได้ทั้ง 4 หมู่ (A, B, AB, O)","มีโอกาสเป็นเฉพาะหมู่ AB","มีโอกาสเป็นเฉพาะหมู่ A และ B","ไม่มีทางเป็นหมู่ O"]', 0, 'การจับคู่ยีน IA, IB, i ทำให้เกิดจีโนไทป์ได้ครบทั้ง 4 หมู่เลือด', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["พันธุศาสตร์: หมู่เลือด ABO","Regular","L1"]');
