INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SCI_M_025', 'science', 'วิทยาศาสตร์', 'Regular', 2, 'ดาราศาสตร์: สุริยุปราคาและจันทรุปราคา', 'ปรากฏการณ์ จันทรุปราคา เกิดขึ้นเมื่อวัตถุท้องฟ้าเรียงตัวในลักษณะใด (ข้อที่ 25)', '["ดวงอาทิตย์ - โลก - ดวงจันทร์","ดวงอาทิตย์ - ดวงจันทร์ - โลก","โลก - ดวงอาทิตย์ - ดวงจันทร์","ดวงจันทร์ - โลก - ดวงอาทิตย์"]', 0, 'จันทรุปราคาเกิดเมื่อโลกอยู่ตรงกลาง บังแสงอาทิตย์ไม่ให้ส่องไปยังดวงจันทร์ในคืนวันเพ็ญ', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ดาราศาสตร์: สุริยุปราคาและจันทรุปราคา","Regular","M"]');
