INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_L1_008', 'social', 'สังคมศึกษา', 'Regular', 1, 'ประวัติศาสตร์ไทย', 'พระมหากษัตริย์พระองค์ใดทรงประดิษฐ์ ''ลายสือไทย'' ขึ้นเป็นครั้งแรกเมื่อ พ.ศ. 1826 (ข้อที่ 8)', '["พ่อขุนรามคำแหงมหาราช","พ่อขุนศรีอินทราทิตย์","สมเด็จพระนเรศวรมหาราช","สมเด็จพระนารายณ์มหาราช"]', 0, 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ลายสือไทยขึ้นเมื่อ พ.ศ. 1826 ในสมัยสุโขทัย', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ประวัติศาสตร์ไทย","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_L1_009', 'social', 'สังคมศึกษา', 'Regular', 1, 'พระพุทธศาสนา: วันสำคัญ', 'วันสำคัญทางพระพุทธศาสนาที่มีเหตุการณ์ ''ประสูติ ตรัสรู้ ปรินิพพาน'' คือวันใด (ข้อที่ 9)', '["วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6)","วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3)","วันอาสาฬหบูชา","วันอัฏฐมีบูชา"]', 0, 'วันวิสาขบูชา เป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพานของพระพุทธเจ้า', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["พระพุทธศาสนา: วันสำคัญ","Regular","L1"]');
