INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_L1_022', 'social', 'สังคมศึกษา', 'Regular', 1, 'หน้าที่พลเมือง: รัฐธรรมนูญ', 'อำนาจอธิปไตยของปวงชนชาวไทยแบ่งออกเป็น 3 ฝ่ายตามข้อใด (ข้อที่ 22)', '["นิติบัญญัติ, บริหาร, ตุลาการ","รัฐสภา, กองทัพ, ศาล","ผู้ว่าราชการ, นายอำเภอ, กำนัน","นายกรัฐมนตรี, รัฐมนตรี, ข้าราชการ"]', 0, 'อำนาจอธิปไตยแบ่งออกเป็น 3 ฝ่ายคือ นิติบัญญัติ (รัฐสภา), บริหาร (ครม.), ตุลาการ (ศาล)', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["หน้าที่พลเมือง: รัฐธรรมนูญ","Regular","L1"]');
INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_L1_023', 'social', 'สังคมศึกษา', 'Regular', 1, 'เศรษฐศาสตร์: กลไกราคา', 'ตามกฎของอุปสงค์ (Law of Demand) เมื่อราคาสินค้าสูงขึ้น ปริมาณความต้องการซื้อจะเป็นอย่างไร (ข้อที่ 23)', '["ลดลง","เพิ่มขึ้น","คงที่","ไม่แน่นอน"]', 0, 'กฎอุปสงค์: ราคาและปริมาณซื้อแปรผกผันกัน ถ้าราคาสูงขึ้น ผู้บริโภคจะซื้อน้อยลง', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["เศรษฐศาสตร์: กลไกราคา","Regular","L1"]');
