INSERT INTO questions (id, subject, subject_name, track, difficulty, topic, question, options_json, correct_answer, explanation, trap, shortcut_trick, tags_json) VALUES ('SOC_L2_011', 'social', 'สังคมศึกษา', 'Regular', 2, 'ประวัติศาสตร์ไทย', 'พระมหากษัตริย์พระองค์ใดทรงประดิษฐ์ ''ลายสือไทย'' ขึ้นเป็นครั้งแรกเมื่อ พ.ศ. 1826 (ข้อที่ 11)', '["พ่อขุนรามคำแหงมหาราช","พ่อขุนศรีอินทราทิตย์","สมเด็จพระนเรศวรมหาราช","สมเด็จพระนารายณ์มหาราช"]', 0, 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ลายสือไทยขึ้นเมื่อ พ.ศ. 1826 ในสมัยสุโขทัย', 'อ่านเงื่อนไขของโจทย์ให้รอบคอบ', 'วิเคราะห์ทีละขั้นตอนตามหลักวิชาการ', '["ประวัติศาสตร์ไทย","Regular","L2"]');
